def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 100:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    coops = sum(1 for a in opp if a == 'C')
    defs = n - coops
    my_defs = sum(1 for a in me if a == 'D')
    if n >= 1 and opp[-1] == 'D':
        if n < 3:
            return 'D'
        burst = 0
        i = len(opp) - 1
        while i >= 0 and opp[i] == 'D':
            burst += 1
            i -= 1
        if burst >= 2:
            if n < 98 and burst < 4 and my_defs < 30:
                return 'C'
        return 'D'
    if n >= 2 and opp[-1] == 'C' and opp[-2] == 'C':
        if n >= 94:
            return 'C'
        if defs <= 2 and n < 40:
            return 'D'
        if my_defs < 4 and n % 7 == 0 and n < 80:
            return 'D'
        return 'C'
    if n == 1:
        return 'C'
    if defs == 0:
        if n == 99:
            return 'D'
        if n > 90:
            return 'D'
        if n > 70 and opp[-1] == 'C':
            return 'D'
        return 'C'
    if coops > defs * 3:
        if n > 95:
            return 'D'
        if n % 11 == 0 and my_defs < defs:
            return 'C'
        return 'C'
    if defs > coops * 2:
        if n > 90 and opp[-1] == 'C' and opp[-2] == 'C' and opp[-3] == 'C':
            return 'D'
        if n < 10:
            return 'D'
        if opp[-1] == 'D' or opp[-2] == 'D':
            return 'D'
        return 'C'
    if n in (97, 98, 99):
        if opp[-1] == 'C':
            return 'D'
    if opp[-1] == 'C' and (n < 2 or opp[-2] == 'C'):
        if n > 85:
            return 'D'
        return 'C'
    if opp[-1] == 'C':
        if n > 80:
            return 'D'
        return 'C'
    return 'D'
